/// Chunk size used when streaming static files off disk (64 KiB).
const STREAM_CHUNK_BYTES: usize = 64 * 1024;

/// Maximum number of 64 KiB chunks read in a single blocking-pool task (256 KiB total), returned
/// as separate frames of at most 64 KiB each so wire frame sizes do not change.
const STREAM_BATCH_CHUNKS: usize = 4;

/// Process-wide ceiling on speculative read-ahead bytes across all active [`StaticFileStream`]
/// bodies (chunks 2..=4 of each batch, covering in-flight pool tasks, completed results awaiting a
/// poll, and queued frames awaiting delivery).
///
/// Chosen at 64 MiB (= 1,024 × 64 KiB chunks, matching `FileCache`'s default 64 MiB budget and
/// `compress`'s 64 MiB compressed-cache budget):
/// - Each full 4-chunk batch reserves at most 3 × 64 KiB = 192 KiB of speculative bytes (chunk 1
///   is the demanded frame, not speculative).
/// - With 100 stalled HTTP/2 streams (each holding up to 256 KiB: one <= 64 KiB frame in hyper /
///   `PieceBody` and up to three 64 KiB frames queued in the body), speculative bytes total at
///   most 100 × 192 KiB = 18.75 MiB (25 MiB including hyper's lookahead), leaving ample room for
///   active streams to keep batching.
/// - With 10,000 stalled HTTP/2 streams, uncapped 3-chunk lookahead would hold ~1.83 GiB of
///   speculative frames; this 64 MiB ceiling caps speculative memory at <= 64 MiB (~341 full
///   3-chunk batches), and every further stream immediately falls back to reading 1 chunk per pool
///   task (0 speculative bytes in the body; only hyper's own 64 KiB lookahead frame).
const STREAM_SPECULATIVE_BUDGET_BYTES: usize = 64 * 1024 * 1024;

/// Files <= 256 KiB are read into a single `Bytes` buffer; larger files stream lazily on demand.
const IN_MEMORY_THRESHOLD_BYTES: u64 = 256 * 1024;

/// Process-wide counter of currently reserved speculative stream bytes.
static STREAM_SPECULATIVE_USED: AtomicUsize = AtomicUsize::new(0);

#[cfg(any(test, debug_assertions))]
static STREAM_DEBUG_BATCHES_STARTED: AtomicUsize = AtomicUsize::new(0);
#[cfg(any(test, debug_assertions))]
static STREAM_DEBUG_BATCHES_COMPLETED: AtomicUsize = AtomicUsize::new(0);
#[cfg(any(test, debug_assertions))]
static STREAM_DEBUG_CHUNKS_READ: AtomicUsize = AtomicUsize::new(0);
#[cfg(any(test, debug_assertions))]
static STREAM_DEBUG_BYTES_READ: AtomicUsize = AtomicUsize::new(0);
#[cfg(any(test, debug_assertions))]
static STREAM_DEBUG_FRAMES_DELIVERED: AtomicUsize = AtomicUsize::new(0);

/// Returns the current process-wide speculative stream bytes reserved (in-flight, completed awaiting
/// poll, and queued). Exposed as `#[doc(hidden)]` for cross-crate integration tests.
#[doc(hidden)]
#[must_use]
pub fn stream_speculative_used_bytes() -> usize {
    STREAM_SPECULATIVE_USED.load(Ordering::Acquire)
}

/// Snapshot of process-wide streamed-body blocking-pool counters (available in test and
/// debug-assertion builds for cross-crate HTTP/2 zero-window read-count tests, matching
/// `CacheClock::system_read_count`).
#[cfg(any(test, debug_assertions))]
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct StreamPoolDebugStats {
    /// Blocking-pool batch tasks submitted.
    pub batches_started: usize,
    /// Blocking-pool batch tasks completed.
    pub batches_completed: usize,
    /// Individual positional chunk reads performed across all batches.
    pub chunks_read: usize,
    /// Total file bytes read across all batches.
    pub bytes_read: usize,
    /// Data frames emitted by `StaticFileStream` to callers.
    pub frames_delivered: usize,
}

/// Returns the current process-wide streamed-body blocking-pool counters (available in test and
/// debug-assertion builds).
#[cfg(any(test, debug_assertions))]
#[doc(hidden)]
#[must_use]
pub fn stream_pool_debug_stats() -> StreamPoolDebugStats {
    StreamPoolDebugStats {
        batches_started: STREAM_DEBUG_BATCHES_STARTED.load(Ordering::Acquire),
        batches_completed: STREAM_DEBUG_BATCHES_COMPLETED.load(Ordering::Acquire),
        chunks_read: STREAM_DEBUG_CHUNKS_READ.load(Ordering::Acquire),
        bytes_read: STREAM_DEBUG_BYTES_READ.load(Ordering::Acquire),
        frames_delivered: STREAM_DEBUG_FRAMES_DELIVERED.load(Ordering::Acquire),
    }
}

thread_local! {
    /// `true` only on OS threads running MiraServe's dedicated single-threaded worker event
    /// loops (`server { workers ... }`). Always `false` on the shared multi-thread runtime and
    /// on blocking-pool threads.
    static ON_WORKER_LOOP: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };

    /// `true` while the current thread is polling an in-task HTTP/2 stream future where
    /// synchronous storage I/O or unbounded compression would stall sibling streams on the same
    /// connection. Always `false` outside those polls (including HTTP/1.1 connections, spawned
    /// HTTP/2 stream tasks, and blocking-pool threads).
    static NONBLOCKING_INLINE_CONTEXT: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// Returns `true` when the current OS thread is one of MiraServe's single-threaded worker event
/// loops (`server { workers ... }`). Always `false` on the shared runtime and on blocking-pool
/// threads.
///
/// Use this only for properties of dedicated worker event loops themselves (such as avoiding
/// placing background cache sweeps onto a single-thread worker runtime). Code deciding whether
/// inline request work may block must call [`inline_work_must_not_block`] instead.
#[must_use]
pub fn is_worker_loop_thread() -> bool {
    ON_WORKER_LOOP.with(std::cell::Cell::get)
}

/// Returns `true` while the current thread is inside [`enter_nonblocking_inline_context`] (polling
/// an in-task HTTP/2 stream future). Always `false` for HTTP/1.1 requests, spawned HTTP/2 stream
/// tasks, and blocking-pool threads.
#[must_use]
pub fn in_nonblocking_inline_context() -> bool {
    NONBLOCKING_INLINE_CONTEXT.with(std::cell::Cell::get)
}

/// Returns `true` when inline work on the current thread must not block on storage or long CPU
/// bursts because other connections (dedicated worker event loop) or sibling HTTP/2 streams
/// (in-task HTTP/2 driver) share this thread/task.
///
/// Always `false` on shared-runtime HTTP/1.1 connections, spawned HTTP/2 stream tasks, and
/// blocking-pool threads.
#[must_use]
pub fn inline_work_must_not_block() -> bool {
    ON_WORKER_LOOP.with(std::cell::Cell::get)
        || NONBLOCKING_INLINE_CONTEXT.with(std::cell::Cell::get)
}

/// Guard returned by [`enter_worker_loop_thread`] that restores the previous thread-local
/// worker-loop state on drop. Marked `!Send` and `!Sync` because it restores state on the
/// thread where it was created.
#[derive(Debug)]
pub struct WorkerLoopThreadGuard {
    prev: bool,
    _not_send: std::marker::PhantomData<std::rc::Rc<()>>,
}

impl Drop for WorkerLoopThreadGuard {
    fn drop(&mut self) {
        ON_WORKER_LOOP.with(|flag| flag.set(self.prev));
    }
}

/// Marks the current OS thread as a single-threaded worker event loop until the returned guard
/// drops. Blocking-pool threads started by this thread's runtime do not inherit this flag.
#[must_use]
pub fn enter_worker_loop_thread() -> WorkerLoopThreadGuard {
    let prev = ON_WORKER_LOOP.with(|flag| flag.replace(true));
    WorkerLoopThreadGuard {
        prev,
        _not_send: std::marker::PhantomData,
    }
}

/// Guard returned by [`enter_nonblocking_inline_context`] that restores the previous thread-local
/// non-blocking context on drop (including during stack unwinding after a panic).
///
/// Marked `!Send` and `!Sync` so it cannot be moved across threads (which would leave the origin
/// thread marked and corrupt the destination thread's state). Prefer the closure-scoped
/// [`with_nonblocking_inline_context`] API so the mark cannot be held across an `.await` point.
#[derive(Debug)]
pub struct NonblockingInlineContextGuard {
    prev: bool,
    _not_send: std::marker::PhantomData<std::rc::Rc<()>>,
}

impl Drop for NonblockingInlineContextGuard {
    fn drop(&mut self) {
        NONBLOCKING_INLINE_CONTEXT.with(|flag| flag.set(self.prev));
    }
}

/// Marks the current thread as polling an in-task HTTP/2 stream future until the returned guard
/// drops, so inline static lookups/reads and proxied-response compression take their non-blocking
/// paths without claiming to be a dedicated worker event loop.
///
/// Prefer [`with_nonblocking_inline_context`] for synchronous poll scopes so the guard cannot be
/// held across an `.await` point.
#[must_use]
pub fn enter_nonblocking_inline_context() -> NonblockingInlineContextGuard {
    let prev = NONBLOCKING_INLINE_CONTEXT.with(|flag| flag.replace(true));
    NonblockingInlineContextGuard {
        prev,
        _not_send: std::marker::PhantomData,
    }
}

/// Runs synchronous closure `f` with the current thread marked as polling an in-task HTTP/2
/// stream future, restoring the previous thread-local state on return or panic unwind.
///
/// Because the scope ends synchronously when `f` returns, the non-blocking marker cannot leak
/// across an `.await` point onto unrelated tasks sharing the thread.
pub fn with_nonblocking_inline_context<R>(f: impl FnOnce() -> R) -> R {
    let _guard = enter_nonblocking_inline_context();
    f()
}

/// Whether non-blocking inline static serving (`openat2(RESOLVE_CACHED)` +
/// `statx(AT_STATX_DONT_SYNC)` + `preadv2(RWF_NOWAIT)` on Linux 5.12–6.11) is available in this
/// process, and why it is unavailable otherwise.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum NonblockingStaticSupport {
    /// Non-blocking lookups and small-file reads are available (`openat2`, `RESOLVE_CACHED`, and
    /// kernel release in Linux 5.12–6.11).
    Available,
    /// Non-Linux platform (no `openat2` / `RESOLVE_CACHED` / `preadv2(RWF_NOWAIT)`).
    UnsupportedPlatform,
    /// `openat2(2)` is refused (kernel older than Linux 5.6 or a system-call filter such as
    /// systemd `RestrictSUIDSGID=yes`).
    Openat2Unavailable,
    /// `openat2(2)` works, but `RESOLVE_CACHED` is unsupported (`EINVAL`, Linux 5.6–5.11).
    ResolveCachedUnavailable,
    /// Kernel release is outside Linux 5.12–6.11 (or `/proc/sys/kernel/osrelease` is unreadable or
    /// unparseable), so `RESOLVE_CACHED` + I/O-free `preadv2(RWF_NOWAIT)` cannot both be used.
    KernelOutsideNowaitRange,
}

impl NonblockingStaticSupport {
    /// Short stable reason string for startup logs and diagnostics.
    #[must_use]
    pub const fn reason(self) -> &'static str {
        match self {
            Self::Available => {
                "openat2, RESOLVE_CACHED, and Linux 5.12-6.11 non-blocking small-file reads are available"
            }
            Self::UnsupportedPlatform => "non-blocking static I/O requires Linux 5.12-6.11",
            Self::Openat2Unavailable => {
                "openat2 is refused by the kernel or a system-call filter (such as systemd RestrictSUIDSGID=yes)"
            }
            Self::ResolveCachedUnavailable => {
                "openat2 RESOLVE_CACHED is not supported by this kernel (requires Linux 5.12+)"
            }
            Self::KernelOutsideNowaitRange => {
                "kernel release is outside Linux 5.12-6.11 for RESOLVE_CACHED and I/O-free preadv2(RWF_NOWAIT)"
            }
        }
    }
}

/// Reads and caches `/proc/sys/kernel/osrelease` for the Linux kernel-range checks before OS
/// sandboxing (Landlock) is installed, even when the configuration has no static routes.
pub fn warm_nowait_kernel_probe() {
    #[cfg(target_os = "linux")]
    {
        let _ = cached_kernel_release();
    }
}

/// Returns whether the Linux kernel release is in the 5.9–6.11 range where buffered
/// `preadv2(RWF_NOWAIT)` starts no readahead I/O in the caller (`false` on non-Linux platforms).
#[must_use]
pub fn kernel_supports_nowait_read() -> bool {
    #[cfg(target_os = "linux")]
    {
        nowait_read_starts_no_io()
    }
    #[cfg(not(target_os = "linux"))]
    {
        false
    }
}

/// Returns whether the Linux kernel release is in the 5.12–6.11 range required for both
/// `openat2(RESOLVE_CACHED)` (5.12+) and I/O-free buffered `preadv2(RWF_NOWAIT)` (5.9–6.11)
/// (`false` on non-Linux platforms).
#[must_use]
pub fn kernel_supports_h2_intask_static() -> bool {
    #[cfg(target_os = "linux")]
    {
        kernel_in_h2_intask_range()
    }
    #[cfg(not(target_os = "linux"))]
    {
        false
    }
}

/// Actively probes `openat2(2)` and `openat2(RESOLVE_CACHED)` in the current thread when the host
/// kernel is in Linux 5.12–6.11 (intended to run at startup or reload only when HTTP/2 and static
/// file work are configured), then returns the resulting [`NonblockingStaticSupport`].
///
/// Outside Linux 5.12–6.11 (or on non-Linux platforms) this returns immediately WITHOUT issuing
/// `openat2(2)`.
#[must_use]
pub fn probe_nonblocking_static_support() -> NonblockingStaticSupport {
    #[cfg(target_os = "linux")]
    {
        if !kernel_in_h2_intask_range() {
            return NonblockingStaticSupport::KernelOutsideNowaitRange;
        }
        run_openat2_capability_probe();
        NONBLOCKING_STATIC_PROBED.store(true, Ordering::Release);
    }
    nonblocking_static_support()
}

/// Returns the current process capability for non-blocking inline static serving.
///
/// Outside Linux 5.12–6.11 (or on non-Linux platforms) this short-circuits WITHOUT issuing
/// `openat2(2)`. Inside Linux 5.12–6.11, runs the side-effect-free `openat2` + `RESOLVE_CACHED`
/// probe once on first call if [`probe_nonblocking_static_support`] has not yet been called, and
/// reflects the live `OPENAT2_UNAVAILABLE` / `RESOLVE_CACHED_UNAVAILABLE` latches.
#[must_use]
pub fn nonblocking_static_support() -> NonblockingStaticSupport {
    #[cfg(target_os = "linux")]
    {
        if !kernel_in_h2_intask_range() {
            return NonblockingStaticSupport::KernelOutsideNowaitRange;
        }
        if !NONBLOCKING_STATIC_PROBED.load(Ordering::Acquire) {
            run_openat2_capability_probe();
            NONBLOCKING_STATIC_PROBED.store(true, Ordering::Release);
        }
        if OPENAT2_UNAVAILABLE.load(Ordering::Relaxed) {
            return NonblockingStaticSupport::Openat2Unavailable;
        }
        if RESOLVE_CACHED_UNAVAILABLE.load(Ordering::Relaxed) {
            return NonblockingStaticSupport::ResolveCachedUnavailable;
        }
        NonblockingStaticSupport::Available
    }
    #[cfg(not(target_os = "linux"))]
    {
        NonblockingStaticSupport::UnsupportedPlatform
    }
}

/// Isolated speculative-byte budget injected by unit tests so parallel tests can exercise tight
/// ceilings and assert exact in-flight / awaiting-poll / queued / peak accounting without racing.
#[cfg(test)]
#[derive(Debug)]
struct TestSpeculativeBudget {
    limit: usize,
    used: AtomicUsize,
    peak: AtomicUsize,
}

#[cfg(test)]
impl TestSpeculativeBudget {
    fn new(limit: usize) -> Arc<Self> {
        Arc::new(Self {
            limit,
            used: AtomicUsize::new(0),
            peak: AtomicUsize::new(0),
        })
    }

    fn used(&self) -> usize {
        self.used.load(Ordering::Acquire)
    }

    fn peak(&self) -> usize {
        self.peak.load(Ordering::Acquire)
    }
}

/// Handle to the speculative-byte budget used by a [`StaticFileStream`]. Zero-sized in non-test
/// builds (always targeting the process-wide [`STREAM_SPECULATIVE_USED`] atomic).
#[cfg(not(test))]
#[derive(Clone, Copy, Debug)]
struct SpeculativeBudgetRef;

#[cfg(test)]
#[derive(Clone, Debug)]
struct SpeculativeBudgetRef {
    custom: Option<Arc<TestSpeculativeBudget>>,
}

impl SpeculativeBudgetRef {
    #[cfg(not(test))]
    const fn capture() -> Self {
        Self
    }

    #[cfg(test)]
    fn capture(hooks: &test_hooks::CapturedHooks) -> Self {
        let custom = hooks.as_ref().and_then(|h| {
            h.stream_budget
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .clone()
        });
        Self { custom }
    }

    #[cfg_attr(
        not(test),
        allow(clippy::unused_self, clippy::trivially_copy_pass_by_ref)
    )]
    fn empty_reservation(&self) -> SpeculativeReservation {
        SpeculativeReservation {
            bytes: 0,
            #[cfg(test)]
            custom: self.custom.clone(),
        }
    }

    /// Reserves `bytes` from the budget without waiting. Returns `None` immediately on exhaustion.
    #[cfg_attr(not(test), allow(clippy::trivially_copy_pass_by_ref))]
    fn try_reserve(&self, bytes: usize) -> Option<SpeculativeReservation> {
        if bytes == 0 {
            return Some(self.empty_reservation());
        }
        #[cfg(test)]
        let (counter, limit) = match self.custom.as_ref() {
            Some(custom) => (&custom.used, custom.limit),
            None => (&STREAM_SPECULATIVE_USED, STREAM_SPECULATIVE_BUDGET_BYTES),
        };
        #[cfg(not(test))]
        let (counter, limit) = (&STREAM_SPECULATIVE_USED, STREAM_SPECULATIVE_BUDGET_BYTES);

        let mut cur = counter.load(Ordering::Acquire);
        loop {
            let next = cur.checked_add(bytes)?;
            if next > limit {
                return None;
            }
            match counter.compare_exchange_weak(cur, next, Ordering::AcqRel, Ordering::Acquire) {
                Ok(_) => {
                    #[cfg(test)]
                    if let Some(custom) = self.custom.as_ref() {
                        custom.peak.fetch_max(next, Ordering::AcqRel);
                    }
                    return Some(SpeculativeReservation {
                        bytes,
                        #[cfg(test)]
                        custom: self.custom.clone(),
                    });
                }
                Err(observed) => cur = observed,
            }
        }
    }
}

/// RAII token owning `bytes` reserved from the speculative stream budget. Releases automatically
/// on delivery, EOF, error, or cancellation (including when a running blocking-pool task outlives
/// a dropped [`StaticFileStream`]).
#[derive(Debug)]
struct SpeculativeReservation {
    bytes: usize,
    #[cfg(test)]
    custom: Option<Arc<TestSpeculativeBudget>>,
}

impl SpeculativeReservation {
    /// Transfers `amount` bytes from this reservation into a new owned reservation with zero
    /// atomic operations.
    fn split_off(&mut self, amount: usize) -> Self {
        let taken = amount.min(self.bytes);
        self.bytes = self.bytes.saturating_sub(taken);
        Self {
            bytes: taken,
            #[cfg(test)]
            custom: self.custom.clone(),
        }
    }
}

impl Drop for SpeculativeReservation {
    fn drop(&mut self) {
        if self.bytes == 0 {
            return;
        }
        #[cfg(test)]
        if let Some(custom) = self.custom.as_ref() {
            custom.used.fetch_sub(self.bytes, Ordering::Release);
            return;
        }
        STREAM_SPECULATIVE_USED.fetch_sub(self.bytes, Ordering::Release);
    }
}

/// How a static lookup and body read may execute.
#[derive(Clone, Copy, PartialEq, Eq)]
enum InlineMode {
    /// Blocking pool thread: complete lookup (following confined symlinks) and blocking reads.
    BlockingPool,
    /// Inline on the shared multi-thread runtime: v0.1.2 inline path for lookups and small files.
    SharedInline,
    /// Inline on a dedicated worker event loop: non-blocking `openat2(RESOLVE_CACHED)`,
    /// `statx(AT_EMPTY_PATH | AT_STATX_DONT_SYNC)`, and (on Linux 5.9–6.11 for small files
    /// `<= 256 KiB`) `preadv2(RWF_NOWAIT)`, falling back to the blocking pool on `EAGAIN`, short
    /// read, or unsupported kernel/syscall/flags.
    #[cfg_attr(not(target_os = "linux"), allow(dead_code))]
    WorkerNonBlocking,
}

impl InlineMode {
    const fn is_inline(self) -> bool {
        !matches!(self, Self::BlockingPool)
    }

    const fn is_nonblocking(self) -> bool {
        matches!(self, Self::WorkerNonBlocking)
    }
}

