#[derive(Debug)]
struct QueuedFrame {
    bytes: Bytes,
    reservation: SpeculativeReservation,
}

/// Inline fixed-capacity FIFO queue holding up to `STREAM_BATCH_CHUNKS - 1` (= 3) speculative
/// frames read ahead by one blocking-pool batch (zero container heap allocation).
#[derive(Debug, Default)]
struct SpeculativeQueue {
    frames: [Option<QueuedFrame>; STREAM_BATCH_CHUNKS - 1],
    head: u8,
    len: u8,
}

impl SpeculativeQueue {
    fn push(&mut self, frame: QueuedFrame) {
        let idx = usize::from(self.head).saturating_add(usize::from(self.len));
        if let Some(slot) = self.frames.get_mut(idx) {
            *slot = Some(frame);
            self.len = self.len.saturating_add(1);
        }
    }

    fn pop_front(&mut self) -> Option<QueuedFrame> {
        if self.len == 0 {
            return None;
        }
        let idx = usize::from(self.head);
        let frame = self.frames.get_mut(idx).and_then(Option::take)?;
        self.head = self.head.saturating_add(1);
        self.len = self.len.saturating_sub(1);
        Some(frame)
    }

    const fn is_empty(&self) -> bool {
        self.len == 0
    }

    fn total_bytes(&self) -> u64 {
        let mut total = 0_u64;
        let start = usize::from(self.head);
        let end = start.saturating_add(usize::from(self.len));
        if let Some(slice) = self.frames.get(start..end) {
            for frame in slice.iter().flatten() {
                total = total.saturating_add(frame.bytes.len() as u64);
            }
        }
        total
    }
}

