#[derive(Debug)]
struct StaticFileStream {
    file: Arc<std::fs::File>,
    /// Next undelivered byte offset in the file; advances strictly by bytes actually emitted.
    offset: u64,
    /// Undelivered bytes remaining in the selected range (includes bytes held in `queued`, and
    /// narrows to the actually read queued bytes once a batch observes early EOF or a read error).
    remaining: u64,
    queued: SpeculativeQueue,
    /// Deferred read error from the current batch, reported after earlier frames in `queued` drain.
    pending_error: Option<std::io::Error>,
    in_flight: Option<tokio::task::JoinHandle<BatchResult>>,
    budget: SpeculativeBudgetRef,
    #[cfg(test)]
    batch_index: usize,
    #[cfg(test)]
    hooks: test_hooks::CapturedHooks,
}

impl Drop for StaticFileStream {
    fn drop(&mut self) {
        if let Some(handle) = self.in_flight.take() {
            handle.abort();
        }
    }
}

type FramePoll = Poll<Option<Result<Frame<Bytes>, std::io::Error>>>;

/// Runs one blocking-pool read batch for [`StaticFileStream`], reading up to `max_chunks` separate
/// `<= 64 KiB` frames starting at `start_offset` within `max_batch_bytes` and never waiting for
/// network credit. Releases any unused speculative reservation and the cloned descriptor before
/// returning.
#[allow(clippy::too_many_arguments)]
fn read_batch_positional_blocking(
    file: Arc<std::fs::File>,
    start_offset: u64,
    max_chunks: usize,
    max_batch_bytes: usize,
    mut batch_reservation: SpeculativeReservation,
    #[cfg(test)] batch_idx: usize,
    #[cfg(test)] hooks: test_hooks::CapturedHooks,
) -> BatchResult {
    #[cfg(test)]
    test_hooks::with_captured(hooks.clone(), || {
        test_hooks::note_stream_pool_task();
        test_hooks::fire_on_stream_pool_read(batch_idx);
    });

    let mut first_frame: Option<Bytes> = None;
    let mut speculative = SpeculativeQueue::default();
    let mut terminal: Option<BatchTerminal> = None;
    let mut cur_offset = start_offset;
    let mut batch_remaining = max_batch_bytes;

    for chunk_in_batch in 0..max_chunks {
        if batch_remaining == 0 {
            break;
        }
        let chunk_max = batch_remaining.min(STREAM_CHUNK_BYTES);
        #[cfg(test)]
        let read_res = test_hooks::with_captured(hooks.clone(), || {
            test_hooks::note_stream_pool_chunk(cur_offset, chunk_max);
            test_hooks::forced_stream_pool_chunk(batch_idx, chunk_in_batch, cur_offset, chunk_max)
                .unwrap_or_else(|| read_chunk_positional_blocking(&file, cur_offset, chunk_max))
        });
        #[cfg(not(test))]
        let read_res = read_chunk_positional_blocking(&file, cur_offset, chunk_max);

        match read_res {
            Ok(bytes) if bytes.is_empty() => {
                terminal = Some(BatchTerminal::Eof);
                break;
            }
            Ok(mut bytes) => {
                if bytes.len() > chunk_max {
                    bytes.truncate(chunk_max);
                }
                let n = bytes.len();
                #[cfg(any(test, debug_assertions))]
                {
                    STREAM_DEBUG_CHUNKS_READ.fetch_add(1, Ordering::Relaxed);
                    STREAM_DEBUG_BYTES_READ.fetch_add(n, Ordering::Relaxed);
                }
                cur_offset = cur_offset.saturating_add(n as u64);
                batch_remaining = batch_remaining.saturating_sub(n);
                if chunk_in_batch == 0 {
                    first_frame = Some(bytes);
                } else {
                    // Charge the allocated chunk capacity reserved for this speculative frame so
                    // reserved bytes stay >= retained heap buffer capacity until delivery or drop.
                    let reservation = batch_reservation.split_off(chunk_max);
                    speculative.push(QueuedFrame { bytes, reservation });
                }
                if n < chunk_max {
                    // A short read inside a batch ends the batch here (without treating it as EOF;
                    // the next poll reads at `cur_offset` and decides).
                    break;
                }
            }
            Err(err) => {
                terminal = Some(BatchTerminal::Error(err));
                break;
            }
        }
    }

    // Release any unused speculative reservation (short read, early EOF, or error) and the cloned
    // descriptor handle before firing completion hooks.
    drop(batch_reservation);
    drop(file);
    #[cfg(any(test, debug_assertions))]
    STREAM_DEBUG_BATCHES_COMPLETED.fetch_add(1, Ordering::Release);
    #[cfg(test)]
    test_hooks::with_captured(hooks, || {
        test_hooks::fire_on_stream_pool_done(batch_idx);
    });
    BatchResult {
        first_frame,
        speculative,
        terminal,
    }
}

impl StaticFileStream {
    fn deliver_bytes(&mut self, bytes: Bytes) -> FramePoll {
        let delivered = (bytes.len() as u64).min(self.remaining);
        self.offset = self.offset.saturating_add(delivered);
        self.remaining = self.remaining.saturating_sub(delivered);
        #[cfg(any(test, debug_assertions))]
        STREAM_DEBUG_FRAMES_DELIVERED.fetch_add(1, Ordering::Release);
        Poll::Ready(Some(Ok(Frame::data(bytes))))
    }

    fn finish_pool_batch(
        &mut self,
        joined: Result<BatchResult, tokio::task::JoinError>,
    ) -> FramePoll {
        match joined {
            Ok(batch) => {
                self.queued = batch.speculative;
                // Early EOF (file shortened in place before the length taken at selection) ends
                // the body cleanly once already-read frames drain, as in v0.1.3/v0.1.4: HTTP/1.1
                // closes short of Content-Length, HTTP/2 peers reject the short stream, and direct
                // body collectors (e.g. Markdown conversion) get what was read. Hard read errors
                // propagate after earlier frames drain, staying observable (`is_end_stream == false`)
                // until reported. In both terminal cases no further pool batch will run, so
                // `remaining` narrows to the bytes actually still to be delivered.
                match batch.terminal {
                    Some(BatchTerminal::Eof) => {
                        let first_len = batch.first_frame.as_ref().map_or(0, |b| b.len() as u64);
                        self.remaining = first_len
                            .saturating_add(self.queued.total_bytes())
                            .min(self.remaining);
                    }
                    Some(BatchTerminal::Error(err)) => {
                        let first_len = batch.first_frame.as_ref().map_or(0, |b| b.len() as u64);
                        self.remaining = first_len
                            .saturating_add(self.queued.total_bytes())
                            .min(self.remaining);
                        self.pending_error = Some(err);
                    }
                    None => {}
                }
                if let Some(first) = batch.first_frame {
                    self.deliver_bytes(first)
                } else if let Some(err) = self.pending_error.take() {
                    self.remaining = 0;
                    Poll::Ready(Some(Err(err)))
                } else {
                    self.remaining = 0;
                    Poll::Ready(None)
                }
            }
            Err(join_err) => {
                self.remaining = 0;
                Poll::Ready(Some(Err(std::io::Error::other(join_err))))
            }
        }
    }

    fn poll_next_frame(&mut self, cx: &mut Context<'_>) -> FramePoll {
        // 1. Drain queued frames one per poll before reporting any pending error or submitting
        //    another pool task.
        if let Some(frame) = self.queued.pop_front() {
            drop(frame.reservation);
            return self.deliver_bytes(frame.bytes);
        }

        // 2. Report any read error that occurred after the frames drained above.
        if let Some(err) = self.pending_error.take() {
            self.remaining = 0;
            return Poll::Ready(Some(Err(err)));
        }

        // 3. Poll an already-submitted blocking-pool batch task.
        if let Some(handle) = self.in_flight.as_mut() {
            return match Pin::new(handle).poll(cx) {
                Poll::Pending => Poll::Pending,
                Poll::Ready(joined) => {
                    self.in_flight = None;
                    self.finish_pool_batch(joined)
                }
            };
        }

        // 4. Nothing queued, no terminal pending, nothing in flight.
        if self.remaining == 0 {
            return Poll::Ready(None);
        }

        // 5. Submit one blocking-pool batch task. Never reserve more speculative bytes than the
        //    remaining length needs; a remaining length <= one chunk reserves 0 and reads 1 chunk.
        let first_chunk_max = usize::try_from(self.remaining.min(STREAM_CHUNK_BYTES as u64))
            .unwrap_or(STREAM_CHUNK_BYTES);
        let speculative_remaining = self.remaining.saturating_sub(first_chunk_max as u64);
        let max_speculative_cap = ((STREAM_BATCH_CHUNKS - 1) * STREAM_CHUNK_BYTES) as u64;
        let want_speculative = usize::try_from(speculative_remaining.min(max_speculative_cap))
            .unwrap_or((STREAM_BATCH_CHUNKS - 1) * STREAM_CHUNK_BYTES);

        let (batch_reservation, max_chunks, max_batch_bytes) = if want_speculative == 0 {
            (self.budget.empty_reservation(), 1_usize, first_chunk_max)
        } else if let Some(res) = self.budget.try_reserve(want_speculative) {
            (
                res,
                STREAM_BATCH_CHUNKS,
                first_chunk_max.saturating_add(want_speculative),
            )
        } else {
            // Speculative budget exhausted: immediately read one chunk per task without waiting.
            (self.budget.empty_reservation(), 1_usize, first_chunk_max)
        };

        let file = Arc::clone(&self.file);
        let start_offset = self.offset;
        #[cfg(test)]
        let batch_idx = self.batch_index;
        #[cfg(test)]
        {
            self.batch_index = self.batch_index.saturating_add(1);
        }
        #[cfg(test)]
        let hooks = self.hooks.clone();
        #[cfg(any(test, debug_assertions))]
        STREAM_DEBUG_BATCHES_STARTED.fetch_add(1, Ordering::Release);

        let handle = tokio::task::spawn_blocking(move || {
            read_batch_positional_blocking(
                file,
                start_offset,
                max_chunks,
                max_batch_bytes,
                batch_reservation,
                #[cfg(test)]
                batch_idx,
                #[cfg(test)]
                hooks,
            )
        });
        let handle = self.in_flight.insert(handle);
        match Pin::new(handle).poll(cx) {
            Poll::Pending => Poll::Pending,
            Poll::Ready(joined) => {
                self.in_flight = None;
                self.finish_pool_batch(joined)
            }
        }
    }
}

#[derive(Debug)]
enum StaticBodyInner {
    Empty,
    Full(Option<Bytes>),
    Stream(Box<StaticFileStream>),
}

impl StaticBody {
    /// Creates an empty body (used for `HEAD`, `304`, `404`, etc.).
    #[must_use]
    pub const fn empty() -> Self {
        Self {
            inner: StaticBodyInner::Empty,
        }
    }

    /// Creates a single-chunk buffered body.
    #[must_use]
    pub fn full(bytes: Bytes) -> Self {
        if bytes.is_empty() {
            Self::empty()
        } else {
            Self {
                inner: StaticBodyInner::Full(Some(bytes)),
            }
        }
    }

    fn streaming(file: std::fs::File, offset: u64, total_bytes: u64) -> Self {
        let file = Arc::new(file);
        #[cfg(test)]
        let hooks = test_hooks::capture();
        #[cfg(test)]
        test_hooks::fire_on_stream_file_created(Arc::downgrade(&file));
        #[cfg(test)]
        let budget = SpeculativeBudgetRef::capture(&hooks);
        #[cfg(not(test))]
        let budget = SpeculativeBudgetRef::capture();
        Self {
            inner: StaticBodyInner::Stream(Box::new(StaticFileStream {
                file,
                offset,
                remaining: total_bytes,
                queued: SpeculativeQueue::default(),
                pending_error: None,
                in_flight: None,
                budget,
                #[cfg(test)]
                batch_index: 0,
                #[cfg(test)]
                hooks,
            })),
        }
    }

    /// Unwraps an empty or single-chunk buffered body without boxing.
    ///
    /// # Errors
    ///
    /// Returns `Err(self)` unchanged when the body is a lazily streamed large file.
    pub fn into_single_chunk(self) -> Result<Option<Bytes>, Self> {
        match self.inner {
            StaticBodyInner::Empty | StaticBodyInner::Full(None) => Ok(None),
            StaticBodyInner::Full(Some(bytes)) => Ok(Some(bytes)),
            stream @ StaticBodyInner::Stream(_) => Err(Self { inner: stream }),
        }
    }
}

impl Body for StaticBody {
    type Data = Bytes;
    type Error = std::io::Error;

    fn poll_frame(
        self: Pin<&mut Self>,
        cx: &mut Context<'_>,
    ) -> Poll<Option<Result<Frame<Self::Data>, Self::Error>>> {
        let this = self.get_mut();
        match &mut this.inner {
            StaticBodyInner::Empty => Poll::Ready(None),
            StaticBodyInner::Full(opt) => match opt.take() {
                Some(b) => Poll::Ready(Some(Ok(Frame::data(b)))),
                None => Poll::Ready(None),
            },
            StaticBodyInner::Stream(stream) => stream.poll_next_frame(cx),
        }
    }

    fn is_end_stream(&self) -> bool {
        match &self.inner {
            StaticBodyInner::Empty | StaticBodyInner::Full(None) => true,
            StaticBodyInner::Full(Some(_)) => false,
            StaticBodyInner::Stream(stream) => {
                stream.remaining == 0 && stream.queued.is_empty() && stream.pending_error.is_none()
            }
        }
    }

    fn size_hint(&self) -> http_body::SizeHint {
        match &self.inner {
            StaticBodyInner::Full(Some(b)) => http_body::SizeHint::with_exact(b.len() as u64),
            StaticBodyInner::Empty | StaticBodyInner::Full(None) => {
                http_body::SizeHint::with_exact(0)
            }
            StaticBodyInner::Stream(stream) => http_body::SizeHint::with_exact(stream.remaining),
        }
    }
}

/// The token names an external ACME client's challenge directory must never answer because a
/// configured credential file has (or would have) that name in that directory. Each path is
/// resolved as its consumer opens it (relative to the working directory; the directory through
/// its links when it exists), whether or not the file exists yet, so restoring a missing key
/// does not make it answerable.
#[must_use]
pub fn reserved_acme_tokens(
    challenge_dir: &Path,
    credentials: &[std::path::PathBuf],
) -> std::collections::HashSet<String> {
    fn resolved_dir(dir: &Path) -> std::path::PathBuf {
        let absolute = if dir.is_absolute() {
            dir.to_path_buf()
        } else {
            std::env::current_dir().map_or_else(|_| dir.to_path_buf(), |cwd| cwd.join(dir))
        };
        std::fs::canonicalize(&absolute).unwrap_or(absolute)
    }
    let challenges = resolved_dir(challenge_dir);
    let mut reserved = std::collections::HashSet::new();
    for credential in credentials {
        // The configured name and, through any links at its end, the file actually opened
        // (also when the link target does not exist yet).
        for path in link_chain(credential) {
            let Some(name) = path.file_name().and_then(|n| n.to_str()) else {
                continue;
            };
            let parent = path.parent().filter(|p| !p.as_os_str().is_empty());
            if is_acme_token(name)
                && resolved_dir(parent.unwrap_or_else(|| Path::new("."))) == challenges
            {
                reserved.insert(name.to_owned());
            }
        }
    }
    reserved
}

/// `path` followed by the targets of the symbolic links at its end, in order (at most 40).
fn link_chain(path: &Path) -> Vec<std::path::PathBuf> {
    let mut chain = vec![path.to_path_buf()];
    let mut current = path.to_path_buf();
    for _ in 0..40 {
        let Ok(target) = std::fs::read_link(&current) else {
            break;
        };
        let next = if target.is_absolute() {
            target
        } else {
            current
                .parent()
                .map_or_else(|| target.clone(), |dir| dir.join(&target))
        };
        chain.push(next.clone());
        current = next;
    }
    chain
}

/// Whether `name` can be an ACME HTTP-01 token MiraServe answers: 1 to 255 base64url
/// characters (`A-Z a-z 0-9 - _`).
#[must_use]
pub fn is_acme_token(name: &str) -> bool {
    !name.is_empty()
        && name.len() <= 255
        && name
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_')
}

/// An internal rewrite target: the (decoded) path with `%`, `?` and `#` escaped, so the first
/// `?` always separates it from the query (`%3F` in a request path stays part of the path).
/// [`decode_rewrite_path`] undoes the escaping of the path part.
#[must_use]
pub fn rewrite_target(path: &str, query: Option<&str>) -> String {
    let mut out = String::with_capacity(path.len() + query.map_or(0, str::len) + 1);
    for ch in path.chars() {
        match ch {
            '%' => out.push_str("%25"),
            '?' => out.push_str("%3F"),
            '#' => out.push_str("%23"),
            other => out.push(other),
        }
    }
    // `Some("")` keeps its `?`: an explicitly empty query is not "no query" (which lets the
    // incoming query through).
    if let Some(query) = query {
        out.push('?');
        out.push_str(query);
    }
    out
}

/// The path part of a [`rewrite_target`] as a decoded path again.
#[must_use]
pub fn decode_rewrite_path(path: &str) -> String {
    let mut out = String::with_capacity(path.len());
    let mut rest = path;
    while let Some(at) = rest.find('%') {
        out.push_str(rest.get(..at).unwrap_or(""));
        let tail = rest.get(at..).unwrap_or("");
        let (decoded, used) = if tail.starts_with("%25") {
            ('%', 3)
        } else if tail.starts_with("%3F") {
            ('?', 3)
        } else if tail.starts_with("%23") {
            ('#', 3)
        } else {
            ('%', 1)
        };
        out.push(decoded);
        rest = tail.get(used..).unwrap_or("");
    }
    out.push_str(rest);
    out
}

/// Outcome of evaluating a `try-files` directive against a static root.
#[derive(Debug)]
pub enum TryFilesOutcome {
    /// A static file or explicit status response (`=404`, `=403`, etc.) was produced for the
    /// request's own path (`{path}` / `{path}/`) or an explicit `=<code>` terminal.
    Response(Box<Response<StaticBody>>),
    /// A static fallback candidate (any candidate other than `{path}` / `{path}/`, such as
    /// `"/index.html"` or `"/shell/"`) produced the response directly inside the static handler
    /// without an internal rewrite. Carries the exact response together with the expanded
    /// candidate path so the router can select route `headers` rules by pure path lookup without
    /// a second dispatch.
    FallbackResponse {
        /// Exact response produced by the static handler (identical to v0.1.3).
        response: Box<Response<StaticBody>>,
        /// Expanded path of the fallback candidate that produced `response`.
        candidate_path: String,
    },
    /// Fallback internal URI rewrite (e.g. `"/index.php?foo=bar"`).
    InternalRewrite(String),
}

/// Outcome of serving a canonical path that may resolve a script directory index or static file.
#[derive(Debug)]
pub enum ScriptOrStaticOutcome {
    /// Static file, static directory slash redirect, or static error response (apply normal
    /// static finishing including Markdown `Vary` hygiene).
    Static(Box<Response<StaticBody>>),
    /// A script directory index triggered a `301` trailing-slash redirect (returned directly
    /// without static Markdown `Vary` finishing, matching v0.1.3).
    ScriptRedirect(Box<Response<StaticBody>>),
    /// A script directory index triggered an internal rewrite to the script URI.
    ScriptRewrite(String),
}

#[cfg_attr(not(any(target_os = "linux", target_os = "android")), allow(dead_code))]
enum LookupFound {
    /// Inline probe opened `rel_path` (a non-directory leaf or directory, matching the base
    /// two-step API; never carries a static directory index descriptor).
    Leaf(FastOpen),
    /// Probe went through the blocking pool on Linux (breaker paused or inline undecided):
    /// serving MUST retain a fresh decision-time status read even if the pause expires before
    /// serving.
    #[cfg(target_os = "linux")]
    Pooled,
}

/// What [`StaticServer::resolve_script_directory_index_keeping`] found when it looked at a path
/// that turned out not to be a directory, together with any pre-probe cache timestamp. Serving the
/// same path next takes it instead of opening the path again; static directory index descriptors
/// are never retained in `Lookup` (they stay private to
/// [`StaticServer::serve_canonical_or_script_index`]), and pooled probes on cache-less servers
/// leave the caller's `Option<Lookup>` as `None` (matching v0.1.3). For any other root or path it
/// is ignored.
pub struct Lookup {
    /// The document root it was made in: another server does not take it.
    root: Arc<Dir>,
    canonical_path: String,
    found: Option<FastOpen>,
    /// Pre-probe cache timestamp and credential epoch sampled before the first filesystem access,
    /// carried independently of whether `found` is `Some` (boxed so cache-off builds/requests keep
    /// `Lookup` compact with zero heap allocation when `None`).
    fill_start: Option<Box<FillStart>>,
}

impl std::fmt::Debug for Lookup {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Lookup")
            .field("canonical_path", &self.canonical_path)
            .finish_non_exhaustive()
    }
}

impl Lookup {
    /// The open result and pre-probe fill snapshot, when made by the server with this `root` for
    /// `canonical_path`.
    fn for_path(
        self,
        root: &Arc<Dir>,
        canonical_path: &str,
    ) -> Option<(Option<LookupFound>, Option<FillStart>)> {
        (Arc::ptr_eq(&self.root, root) && self.canonical_path == canonical_path).then_some((
            self.found.map(LookupFound::Leaf),
            self.fill_start.map(|b| *b),
        ))
    }

    /// The open result only (skipping `fill_start`), when made by the server with this `root` for
    /// `canonical_path`. Used on cache-less servers after testing `file_cache.is_some()`.
    fn found_for_path(self, root: &Arc<Dir>, canonical_path: &str) -> Option<LookupFound> {
        if Arc::ptr_eq(&self.root, root) && self.canonical_path == canonical_path {
            self.found.map(LookupFound::Leaf)
        } else {
            None
        }
    }

    /// Returns the pre-probe [`FillStart`] captured before the probe touched disk, if any.
    #[must_use]
    pub fn fill_start(&self) -> Option<FillStart> {
        self.fill_start.as_deref().copied()
    }
}

/// Test-only recorder of pre-compressed sibling probe attempts (zero-sized no-op in non-test
/// builds).
#[derive(Clone, Default)]
struct SiblingProbeLog {
    #[cfg(test)]
    probed: Arc<std::sync::Mutex<Vec<ContentEncoding>>>,
}

impl std::fmt::Debug for SiblingProbeLog {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("SiblingProbeLog")
    }
}

impl SiblingProbeLog {
    #[allow(clippy::unused_self)]
    fn record(&self, enc: ContentEncoding) {
        #[cfg(test)]
        self.probed
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .push(enc);
        #[cfg(not(test))]
        let _ = enc;
    }

    #[cfg(test)]
    fn take(&self) -> Vec<ContentEncoding> {
        let mut guard = self
            .probed
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        std::mem::take(&mut *guard)
    }
}

const fn precompressed_allows(policy: PrecompressedPolicy, enc: ContentEncoding) -> bool {
    match enc {
        ContentEncoding::Zstd => policy.zst,
        ContentEncoding::Brotli => policy.br,
        ContentEncoding::Gzip => policy.gz,
    }
}

#[cfg(feature = "test-pool-counter")]
static STATIC_BLOCKING_POOL_ENTRIES: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);

/// Returns the number of entries into `miraserve-static`'s blocking-pool fallback closures since
/// process start (integration-test instrumentation; compiled only when the `test-pool-counter`
/// feature is enabled).
#[doc(hidden)]
#[cfg(feature = "test-pool-counter")]
#[must_use]
pub fn static_blocking_pool_entries() -> u64 {
    STATIC_BLOCKING_POOL_ENTRIES.load(std::sync::atomic::Ordering::Acquire)
}

/// Test-only syscall counters, ordered event trace, barriers, and fault injection.
/// Compiles to zero-cost inline no-ops in non-test builds.
#[cfg(test)]
#[allow(dead_code, reason = "some hooks are exercised only on Linux targets")]
mod test_hooks {
    use std::cell::RefCell;
    use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
    use std::sync::{Arc, Mutex};

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub(super) enum TraceEvent {
        OpenLeaf,
        CloseParent,
        ClassifyStat,
        SelectStaticIndex,
        CloseBase,
        PoolDequeue,
        DecisionStat,
        FinalAuth,
        InlineRead,
    }

    pub(super) type HookFn = Box<dyn FnOnce() + Send>;
    pub(super) type ChunkHookFn = Box<dyn FnMut(usize) + Send>;
    pub(super) type StreamPoolChunkHookFn =
        Box<dyn FnMut(usize, usize, u64, usize) -> Option<std::io::Result<bytes::Bytes>> + Send>;
    pub(super) type StreamFileHookFn = Box<dyn FnMut(std::sync::Weak<std::fs::File>) + Send>;
    pub(super) type CapturedHooks = Option<Arc<HookState>>;

    #[derive(Default)]
    pub(super) struct HookState {
        pub(super) opens: AtomicUsize,
        pub(super) stats: AtomicUsize,
        pub(super) parent_closes: AtomicUsize,
        pub(super) base_closes: AtomicUsize,
        pub(super) inline_runs: AtomicUsize,
        pub(super) pool_runs: AtomicUsize,
        pub(super) script_index_runs: AtomicUsize,
        pub(super) stream_pool_tasks: AtomicUsize,
        pub(super) stream_pool_chunks: AtomicUsize,
        pub(super) stream_read_ranges: Mutex<Vec<(u64, usize)>>,
        pub(super) events: Mutex<Vec<TraceEvent>>,
        pub(super) after_selection: Mutex<Option<HookFn>>,
        pub(super) after_parent_close: Mutex<Option<HookFn>>,
        pub(super) after_base_close: Mutex<Option<HookFn>>,
        pub(super) after_pool_dequeue: Mutex<Option<HookFn>>,
        pub(super) before_final_auth: Mutex<Option<HookFn>>,
        pub(super) before_inline_read: Mutex<Option<HookFn>>,
        pub(super) on_classify_stat: Mutex<Option<Box<dyn FnMut() + Send>>>,
        pub(super) on_stream_pool_read: Mutex<Option<ChunkHookFn>>,
        pub(super) on_stream_pool_done: Mutex<Option<ChunkHookFn>>,
        pub(super) on_stream_pool_chunk: Mutex<Option<StreamPoolChunkHookFn>>,
        pub(super) on_stream_file_created: Mutex<Option<StreamFileHookFn>>,
        pub(super) stream_budget: Mutex<Option<Arc<super::TestSpeculativeBudget>>>,
        pub(super) fail_next_classify_stats: AtomicUsize,
        pub(super) fail_next_authoritative_identity: AtomicBool,
    }

    impl std::fmt::Debug for HookState {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            f.debug_struct("HookState")
                .field("stream_pool_tasks", &self.stream_pool_tasks)
                .field("stream_pool_chunks", &self.stream_pool_chunks)
                .finish_non_exhaustive()
        }
    }

    impl HookState {
        pub(super) fn new() -> Arc<Self> {
            Arc::new(Self::default())
        }

        pub(super) fn opens(&self) -> usize {
            self.opens.load(Ordering::Relaxed)
        }

        pub(super) fn stats(&self) -> usize {
            self.stats.load(Ordering::Relaxed)
        }

        pub(super) fn events(&self) -> Vec<TraceEvent> {
            self.events
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .clone()
        }

        pub(super) fn set_after_selection(&self, f: impl FnOnce() + Send + 'static) {
            *self
                .after_selection
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Box::new(f));
        }

        pub(super) fn set_after_parent_close(&self, f: impl FnOnce() + Send + 'static) {
            *self
                .after_parent_close
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Box::new(f));
        }

        pub(super) fn set_after_base_close(&self, f: impl FnOnce() + Send + 'static) {
            *self
                .after_base_close
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Box::new(f));
        }

        pub(super) fn set_after_pool_dequeue(&self, f: impl FnOnce() + Send + 'static) {
            *self
                .after_pool_dequeue
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Box::new(f));
        }

        pub(super) fn set_before_final_auth(&self, f: impl FnOnce() + Send + 'static) {
            *self
                .before_final_auth
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Box::new(f));
        }

        pub(super) fn set_before_inline_read(&self, f: impl FnOnce() + Send + 'static) {
            *self
                .before_inline_read
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Box::new(f));
        }

        pub(super) fn set_on_classify_stat(&self, f: impl FnMut() + Send + 'static) {
            *self
                .on_classify_stat
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Box::new(f));
        }

        pub(super) fn set_on_stream_pool_read(&self, f: impl FnMut(usize) + Send + 'static) {
            *self
                .on_stream_pool_read
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Box::new(f));
        }

        pub(super) fn set_on_stream_pool_done(&self, f: impl FnMut(usize) + Send + 'static) {
            *self
                .on_stream_pool_done
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Box::new(f));
        }

        pub(super) fn set_on_stream_pool_chunk(
            &self,
            f: impl FnMut(usize, usize, u64, usize) -> Option<std::io::Result<bytes::Bytes>>
            + Send
            + 'static,
        ) {
            *self
                .on_stream_pool_chunk
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Box::new(f));
        }

        pub(super) fn set_on_stream_file_created(
            &self,
            f: impl FnMut(std::sync::Weak<std::fs::File>) + Send + 'static,
        ) {
            *self
                .on_stream_file_created
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Box::new(f));
        }

        pub(super) fn set_stream_budget(&self, budget: Arc<super::TestSpeculativeBudget>) {
            *self
                .stream_budget
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(budget);
        }

        pub(super) fn read_ranges(&self) -> Vec<(u64, usize)> {
            self.stream_read_ranges
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .clone()
        }

        fn push_event(&self, ev: TraceEvent) {
            self.events
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .push(ev);
        }
    }

    thread_local! {
        static ACTIVE: RefCell<Option<Arc<HookState>>> = const { RefCell::new(None) };
    }

    pub(super) struct HookGuard {
        prev: Option<Arc<HookState>>,
    }

    impl Drop for HookGuard {
        fn drop(&mut self) {
            let prev = self.prev.take();
            ACTIVE.with(|cell| {
                *cell.borrow_mut() = prev;
            });
        }
    }

    pub(super) fn install(state: Arc<HookState>) -> HookGuard {
        let prev = ACTIVE.with(|cell| cell.borrow_mut().replace(state));
        HookGuard { prev }
    }

    pub(super) fn capture() -> Option<Arc<HookState>> {
        ACTIVE.with(|cell| cell.borrow().clone())
    }

    pub(super) fn with_captured<R>(captured: Option<Arc<HookState>>, f: impl FnOnce() -> R) -> R {
        let _guard = captured.map(install);
        f()
    }

    fn with_active(f: impl FnOnce(&HookState)) {
        let active = ACTIVE.with(|cell| cell.borrow().clone());
        if let Some(state) = active {
            f(&state);
        }
    }

    pub(super) fn note_open() {
        with_active(|s| {
            s.opens.fetch_add(1, Ordering::Relaxed);
        });
    }

    pub(super) fn note_open_leaf() {
        with_active(|s| {
            s.push_event(TraceEvent::OpenLeaf);
        });
    }

    pub(super) fn note_stat() {
        with_active(|s| {
            s.stats.fetch_add(1, Ordering::Relaxed);
        });
    }

    pub(super) fn note_classify_stat() {
        with_active(|s| {
            s.stats.fetch_add(1, Ordering::Relaxed);
            s.push_event(TraceEvent::ClassifyStat);
            if let Some(cb) = s
                .on_classify_stat
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .as_mut()
            {
                cb();
            }
        });
    }

    pub(super) fn note_decision_stat() {
        with_active(|s| {
            s.stats.fetch_add(1, Ordering::Relaxed);
            s.push_event(TraceEvent::DecisionStat);
        });
    }

    pub(super) fn note_parent_close() {
        with_active(|s| {
            s.parent_closes.fetch_add(1, Ordering::Relaxed);
            s.push_event(TraceEvent::CloseParent);
        });
    }

    pub(super) fn note_base_close() {
        with_active(|s| {
            s.base_closes.fetch_add(1, Ordering::Relaxed);
            s.push_event(TraceEvent::CloseBase);
        });
    }

    pub(super) fn note_select_static_index() {
        with_active(|s| {
            s.push_event(TraceEvent::SelectStaticIndex);
        });
    }

    pub(super) fn note_pool_dequeue() {
        with_active(|s| {
            s.push_event(TraceEvent::PoolDequeue);
        });
    }

    pub(super) fn note_final_auth() {
        with_active(|s| {
            s.push_event(TraceEvent::FinalAuth);
        });
    }

    pub(super) fn note_inline_read() {
        with_active(|s| {
            s.push_event(TraceEvent::InlineRead);
        });
    }

    pub(super) fn note_inline_run() {
        with_active(|s| {
            s.inline_runs.fetch_add(1, Ordering::Relaxed);
        });
    }

    pub(super) fn note_pool_run() {
        #[cfg(feature = "test-pool-counter")]
        super::STATIC_BLOCKING_POOL_ENTRIES.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
        with_active(|s| {
            s.pool_runs.fetch_add(1, Ordering::Relaxed);
        });
    }

    #[allow(dead_code)]
    pub(super) fn note_script_index_run() {
        with_active(|s| {
            s.script_index_runs.fetch_add(1, Ordering::Relaxed);
        });
    }

    fn fire_slot(select: impl FnOnce(&HookState) -> &Mutex<Option<HookFn>>) {
        let hook = ACTIVE.with(|cell| {
            cell.borrow().as_ref().and_then(|state| {
                select(state)
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .take()
            })
        });
        if let Some(f) = hook {
            f();
        }
    }

    pub(super) fn fire_after_selection() {
        fire_slot(|s| &s.after_selection);
    }

    pub(super) fn fire_after_parent_close() {
        fire_slot(|s| &s.after_parent_close);
    }

    pub(super) fn fire_after_base_close() {
        fire_slot(|s| &s.after_base_close);
    }

    pub(super) fn fire_after_pool_dequeue() {
        fire_slot(|s| &s.after_pool_dequeue);
    }

    pub(super) fn fire_before_final_auth() {
        fire_slot(|s| &s.before_final_auth);
    }

    pub(super) fn fire_before_inline_read() {
        fire_slot(|s| &s.before_inline_read);
    }

    pub(super) fn should_fail_classify_stat() -> bool {
        let active = ACTIVE.with(|cell| cell.borrow().clone());
        let Some(state) = active else {
            return false;
        };
        let mut cur = state.fail_next_classify_stats.load(Ordering::Relaxed);
        while cur > 0 {
            match state.fail_next_classify_stats.compare_exchange_weak(
                cur,
                cur - 1,
                Ordering::AcqRel,
                Ordering::Relaxed,
            ) {
                Ok(_) => return true,
                Err(next) => cur = next,
            }
        }
        false
    }

    pub(super) fn should_fail_authoritative_identity() -> bool {
        let active = ACTIVE.with(|cell| cell.borrow().clone());
        let Some(state) = active else {
            return false;
        };
        state
            .fail_next_authoritative_identity
            .swap(false, Ordering::AcqRel)
    }

    pub(super) fn note_stream_pool_task() {
        with_active(|s| {
            s.stream_pool_tasks.fetch_add(1, Ordering::Relaxed);
        });
    }

    pub(super) fn note_stream_pool_chunk(offset: u64, max_read: usize) {
        with_active(|s| {
            s.stream_pool_chunks.fetch_add(1, Ordering::Relaxed);
            s.stream_read_ranges
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .push((offset, max_read));
        });
    }

    pub(super) fn forced_stream_pool_chunk(
        batch_idx: usize,
        chunk_in_batch: usize,
        offset: u64,
        max_read: usize,
    ) -> Option<std::io::Result<bytes::Bytes>> {
        let active = ACTIVE.with(|cell| cell.borrow().clone());
        let state = active?;
        state
            .on_stream_pool_chunk
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .as_mut()
            .and_then(|cb| cb(batch_idx, chunk_in_batch, offset, max_read))
    }

    pub(super) fn fire_on_stream_pool_read(batch_idx: usize) {
        with_active(|s| {
            if let Some(cb) = s
                .on_stream_pool_read
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .as_mut()
            {
                cb(batch_idx);
            }
        });
    }

    pub(super) fn fire_on_stream_pool_done(batch_idx: usize) {
        with_active(|s| {
            if let Some(cb) = s
                .on_stream_pool_done
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .as_mut()
            {
                cb(batch_idx);
            }
        });
    }

    pub(super) fn fire_on_stream_file_created(weak: std::sync::Weak<std::fs::File>) {
        with_active(|s| {
            if let Some(cb) = s
                .on_stream_file_created
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .as_mut()
            {
                cb(weak);
            }
        });
    }
}

