    /// [`Self::serve_canonical_with_query`] for a path that
    /// [`Self::resolve_script_directory_index_keeping`] has just looked at: a `lookup` made for
    /// this path by this server is used instead of opening the path a second time. Every rule
    /// on what may be served is applied as without it. Call it at once after the lookup, with
    /// nothing awaited in between: the file's validators are those read when it was opened.
    pub async fn serve_canonical_looked_up(
        &self,
        method: &Method,
        canonical_path: &str,
        query: Option<&str>,
        req_headers: &HeaderMap,
        lookup: Option<Lookup>,
    ) -> Response<StaticBody> {
        // Test the server's cache setting FIRST so cache-less servers never unpack `fill_start`
        // or derive `FillOrigin::Carried`/`SampleHere`.
        let (probe, fill_origin) = if self.file_cache.is_some() {
            match lookup {
                None => (None, FillOrigin::SampleHere),
                Some(lookup) => match lookup.for_path(&self.root, canonical_path) {
                    Some((found, Some(fs))) => (found, FillOrigin::Carried(fs)),
                    Some((found, None)) => (found, FillOrigin::DoNotAdmit),
                    None => (None, FillOrigin::DoNotAdmit),
                },
            }
        } else {
            let probe = lookup.and_then(|l| l.found_for_path(&self.root, canonical_path));
            (probe, FillOrigin::DoNotAdmit)
        };
        self.serve_inner(
            method,
            canonical_path,
            query,
            req_headers,
            &[],
            false,
            true,
            probe,
            fill_origin,
            None,
            RetentionPolicy::TWO_STEP,
            CacheBehavior::UseDirect,
        )
        .await
    }

