    #[cfg(target_os = "linux")]
    #[allow(
        clippy::too_many_arguments,
        clippy::too_many_lines,
        clippy::fn_params_excessive_bools
    )]
    async fn serve_single_pass_linux_caching_inner(
        &self,
        method: &Method,
        path_input: &str,
        query_str: &str,
        req_headers: &HeaderMap,
        decode_percent: bool,
        allow_dir_redirect: bool,
        script_redirect_path: Option<&str>,
        script_extensions: &[String],
        extra_forbidden: &[String],
        runs_script: Option<&ScriptOwner>,
        path_is_forbidden_script: bool,
        mut fill_ctx: FillContext,
    ) -> (ScriptOrStaticOutcome, Option<FillContext>) {
        let (rel_path, trailing_slash) =
            match sanitize_request_path(path_input, self.options.dotfiles, decode_percent) {
                SanitizedPath::Valid {
                    rel,
                    trailing_slash,
                } => (rel, trailing_slash),
                SanitizedPath::BadRequest => {
                    let status = if path_is_forbidden_script {
                        StatusCode::NOT_FOUND
                    } else {
                        StatusCode::BAD_REQUEST
                    };
                    return (
                        ScriptOrStaticOutcome::Static(Box::new(status_response(status))),
                        Some(fill_ctx),
                    );
                }
                SanitizedPath::Forbidden => {
                    return (
                        ScriptOrStaticOutcome::Static(Box::new(status_response(
                            StatusCode::NOT_FOUND,
                        ))),
                        Some(fill_ctx),
                    );
                }
            };

        let forbidden = self.effective_forbidden(extra_forbidden);
        let is_head = method == Method::HEAD;

        let mut selected_static_candidate: Option<PathBuf> = None;

        if let Some(mode) = self.inline_mode() {
            test_hooks::note_inline_run();
            let started = self.breaker_now();
            let inline_res = serve_single_pass_inline_caching(
                &self.root,
                &self.root_read_policy,
                &self.options,
                &self.secret_files,
                &forbidden,
                &rel_path,
                trailing_slash,
                allow_dir_redirect,
                path_input,
                query_str,
                script_redirect_path,
                script_extensions,
                runs_script,
                path_is_forbidden_script,
                is_head,
                req_headers,
                &self.sibling_probes,
                mode,
                &mut fill_ctx,
                self.extra_response_headers,
            );
            self.note_inline_lookup(started);
            match inline_res {
                SinglePassInlineCaching::Done(outcome) => return (outcome, Some(fill_ctx)),
                SinglePassInlineCaching::NeedsPoolTarget(target, base_len) => {
                    let candidate = target.rel_path.clone().into_owned();
                    let (resp, returned_ctx) = self
                        .finish_pool_retained_target_caching(
                            target,
                            base_len,
                            forbidden,
                            rel_path.into_owned(),
                            trailing_slash,
                            allow_dir_redirect,
                            path_input,
                            query_str,
                            is_head,
                            req_headers,
                            None,
                            Some(candidate),
                            fill_ctx,
                        )
                        .await;
                    return (ScriptOrStaticOutcome::Static(Box::new(resp)), returned_ctx);
                }
                SinglePassInlineCaching::FallbackPool => {}
                SinglePassInlineCaching::FallbackStatic { candidate_path } => {
                    selected_static_candidate = Some(candidate_path);
                }
            }
        }

        let root = Arc::clone(&self.root);
        let options = self.options.clone();
        let secret_files = Arc::clone(&self.secret_files);
        let headers = req_headers.clone();
        let req_path = path_input.to_owned();
        let req_query = query_str.to_owned();
        let rel_path = rel_path.into_owned();
        let script_redir = script_redirect_path.map(str::to_owned);
        let script_exts = script_extensions.to_vec();
        let runs_script = runs_script.cloned();
        let sibling_probes = self.sibling_probes.clone();
        let extra_headers = self.extra_response_headers;
        let hooks = test_hooks::capture();

        match tokio::task::spawn_blocking(move || {
            let outcome = test_hooks::with_captured(hooks, || {
                test_hooks::note_pool_run();
                test_hooks::note_pool_dequeue();
                test_hooks::fire_after_pool_dequeue();
                if let Some(candidate_path) = selected_static_candidate {
                    let resp = serve_selected_static_representation_blocking_caching(
                        &root,
                        &options,
                        &secret_files,
                        &forbidden,
                        candidate_path,
                        &req_path,
                        &req_query,
                        is_head,
                        &headers,
                        &sibling_probes,
                        &mut fill_ctx,
                        extra_headers,
                    );
                    return ScriptOrStaticOutcome::Static(Box::new(resp));
                }
                if !script_exts.is_empty() {
                    test_hooks::note_script_index_run();
                    let dir_rel = if rel_path.as_os_str().is_empty() {
                        Path::new(".")
                    } else {
                        rel_path.as_path()
                    };
                    if let Some(ResolvedDirIndex::ScriptRewrite(script_uri)) =
                        resolve_directory_index_sync(
                            &root,
                            dir_rel,
                            &options,
                            &script_exts,
                            &forbidden,
                            runs_script.as_ref(),
                        )
                    {
                        if let Some(redir_path) = script_redir.as_deref() {
                            return ScriptOrStaticOutcome::ScriptRedirect(Box::new(
                                directory_slash_redirect(redir_path, &req_query),
                            ));
                        }
                        let rewritten = rewrite_target(
                            &script_uri,
                            (!req_query.is_empty()).then_some(req_query.as_str()),
                        );
                        return ScriptOrStaticOutcome::ScriptRewrite(rewritten);
                    }
                }
                if path_is_forbidden_script {
                    return ScriptOrStaticOutcome::Static(Box::new(status_response(
                        StatusCode::NOT_FOUND,
                    )));
                }
                let resp = match serve_blocking_caching(
                    &root,
                    None,
                    &options,
                    &secret_files,
                    &forbidden,
                    &rel_path,
                    trailing_slash,
                    allow_dir_redirect,
                    &req_path,
                    &req_query,
                    is_head,
                    &headers,
                    InlineMode::BlockingPool,
                    None,
                    None,
                    &sibling_probes,
                    false,
                    false,
                    false,
                    &mut fill_ctx,
                    extra_headers,
                ) {
                    ServeOutcomeCaching::Done(resp) => resp,
                    ServeOutcomeCaching::NeedsPoolTarget(_, _)
                    | ServeOutcomeCaching::FallbackPool
                    | ServeOutcomeCaching::FallbackFresh => {
                        status_response(StatusCode::INTERNAL_SERVER_ERROR)
                    }
                };
                ScriptOrStaticOutcome::Static(Box::new(resp))
            });
            (outcome, fill_ctx)
        })
        .await
        {
            Ok((outcome, fill_ctx)) => (outcome, Some(fill_ctx)),
            Err(_) => (
                ScriptOrStaticOutcome::Static(Box::new(status_response(
                    StatusCode::INTERNAL_SERVER_ERROR,
                ))),
                None,
            ),
        }
    }
    #[allow(clippy::too_many_arguments)]
    async fn serve_inner(
        &self,
        method: &Method,
        path_input: &str,
        query: Option<&str>,
        req_headers: &HeaderMap,
        extra_forbidden_extensions: &[String],
        decode_percent: bool,
        allow_dir_redirect: bool,
        probe: Option<LookupFound>,
        fill_origin: FillOrigin,
        conversion: Option<&Conversion>,
        retention: RetentionPolicy,
        cache_behavior: CacheBehavior<'_>,
    ) -> Response<StaticBody> {
        if self.file_cache.is_some() {
            return Box::pin(self.serve_inner_cached_entry(
                method,
                path_input,
                query,
                req_headers,
                extra_forbidden_extensions,
                decode_percent,
                allow_dir_redirect,
                probe,
                fill_origin,
                conversion,
                retention,
                cache_behavior,
            ))
            .await;
        }
        self.serve_inner_uncached(
            method,
            path_input,
            query,
            req_headers,
            extra_forbidden_extensions,
            decode_percent,
            allow_dir_redirect,
            probe,
            conversion,
            retention,
            0,
        )
        .await
    }

    #[allow(clippy::too_many_arguments)]
    async fn serve_inner_cached_entry(
        &self,
        method: &Method,
        path_input: &str,
        query: Option<&str>,
        req_headers: &HeaderMap,
        extra_forbidden_extensions: &[String],
        decode_percent: bool,
        allow_dir_redirect: bool,
        probe: Option<LookupFound>,
        fill_origin: FillOrigin,
        conversion: Option<&Conversion>,
        retention: RetentionPolicy,
        cache_behavior: CacheBehavior<'_>,
    ) -> Response<StaticBody> {
        let (rel_path, trailing_slash) =
            match sanitize_request_path(path_input, self.options.dotfiles, decode_percent) {
                SanitizedPath::Valid {
                    rel,
                    trailing_slash,
                } => (rel, trailing_slash),
                SanitizedPath::BadRequest => return status_response(StatusCode::BAD_REQUEST),
                SanitizedPath::Forbidden => return status_response(StatusCode::NOT_FOUND),
            };

        let forbidden = self.effective_forbidden(extra_forbidden_extensions);

        if method != Method::GET && method != Method::HEAD {
            let found = self
                .get_would_find(
                    forbidden,
                    rel_path.into_owned(),
                    trailing_slash,
                    allow_dir_redirect,
                )
                .await;
            return if found {
                method_not_allowed()
            } else {
                status_response(StatusCode::NOT_FOUND)
            };
        }

        let is_head = method == Method::HEAD;
        let req_query = query.unwrap_or("");
        let can_reuse =
            LINUX_ONE_OPEN_ENABLED && retention.allow_reuse && !self.has_unidentified_credential;
        let can_fuse_auth = can_reuse && retention.allow_fusion && probe.is_none();

        let Some(fc) = self.file_cache.as_ref() else {
            return self
                .serve_inner_uncached(
                    method,
                    path_input,
                    query,
                    req_headers,
                    extra_forbidden_extensions,
                    decode_percent,
                    allow_dir_redirect,
                    probe,
                    conversion,
                    retention,
                    0,
                )
                .await;
        };
        self.serve_inner_with_file_cache(
            fc,
            forbidden,
            rel_path.into_owned(),
            trailing_slash,
            allow_dir_redirect,
            path_input,
            req_query,
            is_head,
            req_headers,
            extra_forbidden_extensions,
            decode_percent,
            probe,
            fill_origin,
            conversion,
            can_reuse,
            can_fuse_auth,
            cache_behavior,
        )
        .await
    }

    #[allow(clippy::too_many_arguments)]
    async fn serve_inner_uncached(
        &self,
        method: &Method,
        path_input: &str,
        query: Option<&str>,
        req_headers: &HeaderMap,
        extra_forbidden_extensions: &[String],
        decode_percent: bool,
        allow_dir_redirect: bool,
        probe: Option<LookupFound>,
        conversion: Option<&Conversion>,
        retention: RetentionPolicy,
        extra_header_slots: usize,
    ) -> Response<StaticBody> {
        #[cfg(target_os = "linux")]
        if *method == Method::GET && self.should_spawn_static_task() {
            let srv = self.clone();
            let path_owned = path_input.to_owned();
            let query_owned = query.map(str::to_owned);
            let headers_owned = req_headers.clone();
            let extra_owned = extra_forbidden_extensions.to_vec();
            let conversion_owned = conversion.cloned();
            return Box::pin(run_spawned_static_task(
                async move {
                    srv.serve_inner_uncached_inner(
                        &Method::GET,
                        &path_owned,
                        query_owned.as_deref(),
                        &headers_owned,
                        &extra_owned,
                        decode_percent,
                        allow_dir_redirect,
                        probe,
                        conversion_owned.as_ref(),
                        retention,
                        extra_header_slots,
                    )
                    .await
                },
                || status_response(StatusCode::INTERNAL_SERVER_ERROR),
            ))
            .await;
        }
        self.serve_inner_uncached_inner(
            method,
            path_input,
            query,
            req_headers,
            extra_forbidden_extensions,
            decode_percent,
            allow_dir_redirect,
            probe,
            conversion,
            retention,
            extra_header_slots,
        )
        .await
    }

    #[allow(clippy::too_many_arguments, clippy::too_many_lines)]
    async fn serve_inner_uncached_inner(
        &self,
        method: &Method,
        path_input: &str,
        query: Option<&str>,
        req_headers: &HeaderMap,
        extra_forbidden_extensions: &[String],
        decode_percent: bool,
        allow_dir_redirect: bool,
        probe: Option<LookupFound>,
        conversion: Option<&Conversion>,
        retention: RetentionPolicy,
        extra_header_slots: usize,
    ) -> Response<StaticBody> {
        let (rel_path, trailing_slash) =
            match sanitize_request_path(path_input, self.options.dotfiles, decode_percent) {
                SanitizedPath::Valid {
                    rel,
                    trailing_slash,
                } => (rel, trailing_slash),
                SanitizedPath::BadRequest => return status_response(StatusCode::BAD_REQUEST),
                SanitizedPath::Forbidden => return status_response(StatusCode::NOT_FOUND),
            };

        let forbidden = self.effective_forbidden(extra_forbidden_extensions);

        if method != Method::GET && method != Method::HEAD {
            // 405 only for something a GET would find; a path that would be 404 for GET is 404
            // for every method.
            let found = self
                .get_would_find(
                    forbidden,
                    rel_path.into_owned(),
                    trailing_slash,
                    allow_dir_redirect,
                )
                .await;
            return if found {
                method_not_allowed()
            } else {
                status_response(StatusCode::NOT_FOUND)
            };
        }

        let is_head = method == Method::HEAD;
        let req_query = query.unwrap_or("");
        // Explicit reuse eligibility (separate from single-status fusion): false on non-Linux,
        // deferred paths (authored `.md`, Markdown conversion), and any serving generation that
        // carries `UNIDENTIFIED_CREDENTIAL`.
        let can_reuse =
            LINUX_ONE_OPEN_ENABLED && retention.allow_reuse && !self.has_unidentified_credential;
        // Any carried probe (including private `LookupFound::Pooled` from a pooled script-index
        // probe whose breaker pause expired before serving) or `RetentionPolicy::TWO_STEP`
        // disables single-status-read fusion. An inherited v0.1.3 direct-file probe is still
        // consumed as in v0.1.3 (with v0.1.3's decision-time `is_secret_file` check when
        // `can_reuse` is false under a serving-generation `UNIDENTIFIED_CREDENTIAL` marker).
        let can_fuse_auth = can_reuse && retention.allow_fusion && probe.is_none();
        let mut force_fresh = false;

        let effective_extra_headers = self
            .extra_response_headers
            .saturating_add(extra_header_slots);
        // Verbatim 0.1.4 uncached serving path (non-blocking inline mode on worker loops).
        if let Some(mode) = self.inline_mode() {
            test_hooks::note_inline_run();
            let started = self.breaker_now();
            let served = serve_blocking(
                &self.root,
                Some(&self.root_read_policy),
                &self.options,
                &self.secret_files,
                &forbidden,
                &rel_path,
                trailing_slash,
                allow_dir_redirect,
                path_input,
                req_query,
                is_head,
                req_headers,
                mode,
                probe,
                conversion,
                &self.sibling_probes,
                can_reuse,
                can_fuse_auth,
                false,
                effective_extra_headers,
            );
            self.note_inline_lookup(started);
            match served {
                ServeOutcome::Done(resp) => return resp,
                #[cfg(target_os = "linux")]
                ServeOutcome::NeedsPoolTarget(target) => {
                    return Box::pin(self.finish_pool_retained_target(
                        target,
                        forbidden,
                        rel_path.into_owned(),
                        trailing_slash,
                        allow_dir_redirect,
                        path_input,
                        req_query,
                        is_head,
                        req_headers,
                        conversion,
                        None,
                        effective_extra_headers,
                    ))
                    .await;
                }
                ServeOutcome::FallbackPool => {}
                ServeOutcome::FallbackFresh => {
                    force_fresh = true;
                }
            }
        }

        let root = Arc::clone(&self.root);
        let options = self.options.clone();
        let secret_files = Arc::clone(&self.secret_files);
        let headers = req_headers.clone();
        let req_path = path_input.to_owned();
        let req_query = req_query.to_owned();
        let rel_path = rel_path.into_owned();
        let conversion = conversion.cloned();
        let sibling_probes = self.sibling_probes.clone();
        let extra_headers = effective_extra_headers;
        let hooks = test_hooks::capture();
        tokio::task::spawn_blocking(move || {
            test_hooks::with_captured(hooks, || {
                test_hooks::note_pool_run();
                test_hooks::note_pool_dequeue();
                test_hooks::fire_after_pool_dequeue();
                match serve_blocking(
                    &root,
                    None,
                    &options,
                    &secret_files,
                    &forbidden,
                    &rel_path,
                    trailing_slash,
                    allow_dir_redirect,
                    &req_path,
                    &req_query,
                    is_head,
                    &headers,
                    InlineMode::BlockingPool,
                    None,
                    conversion.as_ref(),
                    &sibling_probes,
                    false,
                    false,
                    force_fresh,
                    extra_headers,
                ) {
                    ServeOutcome::Done(resp) => Some(resp),
                    #[cfg(target_os = "linux")]
                    ServeOutcome::NeedsPoolTarget(_) => None,
                    ServeOutcome::FallbackPool | ServeOutcome::FallbackFresh => None,
                }
            })
        })
        .await
        .ok()
        .flatten()
        .unwrap_or_else(|| status_response(StatusCode::INTERNAL_SERVER_ERROR))
    }

    #[allow(
        clippy::too_many_arguments,
        clippy::too_many_lines,
        clippy::fn_params_excessive_bools
    )]
    async fn serve_inner_with_file_cache(
        &self,
        fc: &SiteFileCache,
        forbidden: Arc<[String]>,
        rel_path: PathBuf,
        trailing_slash: bool,
        allow_dir_redirect: bool,
        path_input: &str,
        req_query: &str,
        is_head: bool,
        req_headers: &HeaderMap,
        extra_forbidden_extensions: &[String],
        decode_percent: bool,
        probe: Option<LookupFound>,
        fill_origin: FillOrigin,
        conversion: Option<&Conversion>,
        can_reuse: bool,
        can_fuse_auth: bool,
        cache_behavior: CacheBehavior<'_>,
    ) -> Response<StaticBody> {
        #[cfg(test)]
        STATIC_CACHE_PATH_CALLS.fetch_add(1, Ordering::Relaxed);
        let (fill_ctx, fill_return_slot) = if fc.has_unidentified_credential
            || conversion.is_some()
            || has_range_headers(req_headers)
        {
            (None, None)
        } else {
            match cache_behavior {
                CacheBehavior::Bypass => (None, None),
                CacheBehavior::FillOnly(slot) => {
                    if is_head {
                        (None, None)
                    } else {
                        (slot.take(), Some(slot))
                    }
                }
                CacheBehavior::UseDirect => {
                    let ctx = if fc.cache.is_enabled()
                        && self.forbidden_extensions_cover(extra_forbidden_extensions)
                    {
                        let key_path = canonical_cache_path(
                            path_input,
                            &rel_path,
                            trailing_slash,
                            decode_percent,
                        );
                        if key_path.len() <= MAX_CACHE_KEY_BYTES {
                            let enc_mask = self.request_enc_mask(req_headers);
                            if let Some(entry) = fc.cache.get_if_fresh(
                                fc.server_id,
                                LookupKind::Direct,
                                enc_mask,
                                &key_path,
                            ) {
                                fc.cache.counters().record_hit();
                                return respond_from_cache(
                                    &entry,
                                    is_head,
                                    req_headers,
                                    self.extra_response_headers,
                                );
                            }
                            fc.cache.counters().record_miss();
                            if is_head {
                                None
                            } else {
                                let start = match fill_origin {
                                    FillOrigin::SampleHere => Some(fc.sample_fill_start()),
                                    FillOrigin::Carried(s) if fc.owns_fill_start(s) => Some(s),
                                    FillOrigin::Carried(_) | FillOrigin::DoNotAdmit => None,
                                };
                                start.map(|s| FillContext {
                                    site_cache: fc.clone(),
                                    kind: LookupKind::Direct,
                                    key_path: key_path.into_owned(),
                                    enc_mask,
                                    expires_at_nanos: fc.deadline_from(s.looked_up_at),
                                    cred_epoch: s.cred_epoch,
                                    pressure: s.pressure,
                                    fallback_candidate_path: None,
                                    #[cfg(test)]
                                    after_resolve_hook: self.after_resolve_hook.clone(),
                                    #[cfg(test)]
                                    before_admit_hook: self.before_admit_hook.clone(),
                                })
                            }
                        } else {
                            None
                        }
                    } else {
                        None
                    };
                    (ctx, None)
                }
            }
        };

        if let Some(fill_ctx) = fill_ctx {
            let (resp, returned_ctx) = self
                .serve_miss_caching(
                    forbidden,
                    rel_path,
                    trailing_slash,
                    allow_dir_redirect,
                    path_input,
                    req_query,
                    is_head,
                    req_headers,
                    probe,
                    conversion,
                    can_reuse,
                    can_fuse_auth,
                    fill_ctx,
                )
                .await;
            if let (Some(slot), Some(ctx)) = (fill_return_slot, returned_ctx) {
                *slot = Some(ctx);
            }
            return resp;
        }

        let mut force_fresh = false;
        #[cfg(target_os = "linux")]
        if !is_head && self.should_spawn_static_task() {
            let srv = self.clone();
            let path_owned = path_input.to_owned();
            let query_owned = req_query.to_owned();
            let headers_owned = req_headers.clone();
            let extra_owned = extra_forbidden_extensions.to_vec();
            let conversion_owned = conversion.cloned();
            let retention = if can_reuse {
                if can_fuse_auth {
                    RetentionPolicy::ELIGIBLE
                } else {
                    RetentionPolicy::TWO_STEP
                }
            } else {
                RetentionPolicy::DEFERRED
            };
            return Box::pin(run_spawned_static_task(
                async move {
                    srv.serve_inner_uncached(
                        &Method::GET,
                        &path_owned,
                        Some(&query_owned),
                        &headers_owned,
                        &extra_owned,
                        decode_percent,
                        allow_dir_redirect,
                        probe,
                        conversion_owned.as_ref(),
                        retention,
                        0,
                    )
                    .await
                },
                || status_response(StatusCode::INTERNAL_SERVER_ERROR),
            ))
            .await;
        }
        if let Some(mode) = self.inline_mode() {
            test_hooks::note_inline_run();
            let started = self.breaker_now();
            let served = serve_blocking(
                &self.root,
                Some(&self.root_read_policy),
                &self.options,
                &self.secret_files,
                &forbidden,
                &rel_path,
                trailing_slash,
                allow_dir_redirect,
                path_input,
                req_query,
                is_head,
                req_headers,
                mode,
                probe,
                conversion,
                &self.sibling_probes,
                can_reuse,
                can_fuse_auth,
                false,
                self.extra_response_headers,
            );
            self.note_inline_lookup(started);
            match served {
                ServeOutcome::Done(resp) => return resp,
                #[cfg(target_os = "linux")]
                ServeOutcome::NeedsPoolTarget(target) => {
                    return self
                        .finish_pool_retained_target(
                            target,
                            forbidden,
                            rel_path,
                            trailing_slash,
                            allow_dir_redirect,
                            path_input,
                            req_query,
                            is_head,
                            req_headers,
                            conversion,
                            None,
                            self.extra_response_headers,
                        )
                        .await;
                }
                ServeOutcome::FallbackPool => {}
                ServeOutcome::FallbackFresh => {
                    force_fresh = true;
                }
            }
        }

        let root = Arc::clone(&self.root);
        let options = self.options.clone();
        let secret_files = Arc::clone(&self.secret_files);
        let headers = req_headers.clone();
        let req_path = path_input.to_owned();
        let req_query = req_query.to_owned();
        let conversion = conversion.cloned();
        let sibling_probes = self.sibling_probes.clone();
        let extra_headers = self.extra_response_headers;
        let hooks = test_hooks::capture();
        tokio::task::spawn_blocking(move || {
            test_hooks::with_captured(hooks, || {
                test_hooks::note_pool_run();
                test_hooks::note_pool_dequeue();
                test_hooks::fire_after_pool_dequeue();
                match serve_blocking(
                    &root,
                    None,
                    &options,
                    &secret_files,
                    &forbidden,
                    &rel_path,
                    trailing_slash,
                    allow_dir_redirect,
                    &req_path,
                    &req_query,
                    is_head,
                    &headers,
                    InlineMode::BlockingPool,
                    None,
                    conversion.as_ref(),
                    &sibling_probes,
                    false,
                    false,
                    force_fresh,
                    extra_headers,
                ) {
                    ServeOutcome::Done(resp) => Some(resp),
                    #[cfg(target_os = "linux")]
                    ServeOutcome::NeedsPoolTarget(_) => None,
                    ServeOutcome::FallbackPool | ServeOutcome::FallbackFresh => None,
                }
            })
        })
        .await
        .ok()
        .flatten()
        .unwrap_or_else(|| status_response(StatusCode::INTERNAL_SERVER_ERROR))
    }

    /// Completes pool-deferred serving on the blocking pool for a target already selected inline
    /// (cold on-the-fly compression, small-file `RWF_NOWAIT` `WouldBlock`, or non-blocking `statx`
    /// fallback): reauthorizes the transferred descriptor after dequeue with the retained-
    /// credential predicate before reading or compressing any bytes, falling back to fresh
    /// resolution only if the serving generation carries `UNIDENTIFIED_CREDENTIAL`.
    #[cfg(target_os = "linux")]
    #[allow(clippy::too_many_arguments, clippy::too_many_lines)]
    async fn finish_pool_retained_target(
        &self,
        mut target: OpenedTarget<'static>,
        forbidden: Arc<[String]>,
        rel_path: PathBuf,
        trailing_slash: bool,
        allow_dir_redirect: bool,
        path_input: &str,
        req_query: &str,
        is_head: bool,
        req_headers: &HeaderMap,
        conversion: Option<&Conversion>,
        selected_static_candidate: Option<PathBuf>,
        extra_headers: usize,
    ) -> Response<StaticBody> {
        let root = Arc::clone(&self.root);
        let options = self.options.clone();
        let secret_files = Arc::clone(&self.secret_files);
        let headers = req_headers.clone();
        let req_path = path_input.to_owned();
        let req_query = req_query.to_owned();
        let conversion = conversion.cloned();
        let sibling_probes = self.sibling_probes.clone();
        let hooks = test_hooks::capture();
        tokio::task::spawn_blocking(move || {
            test_hooks::with_captured(hooks, || {
                #[cfg(all(any(test, feature = "test-h2-hooks"), target_os = "linux"))]
                {
                    let hook = TEST_BLOCKING_POOL_HOOK
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .clone();
                    if let Some(hook) = hook {
                        hook(&target.rel_path);
                    }
                }
                test_hooks::note_pool_run();
                test_hooks::note_pool_dequeue();
                test_hooks::fire_after_pool_dequeue();
                match authorize_retained_fd(&mut target, &secret_files) {
                    RetainedCredentialVerdict::Allowed => {
                        let range_header = headers.get(RANGE).and_then(|v| v.to_str().ok());
                        match respond_with_target(
                            TargetResolution::File(target),
                            None,
                            &options,
                            &req_path,
                            &req_query,
                            is_head,
                            &headers,
                            range_header,
                            InlineMode::BlockingPool,
                            extra_headers,
                        ) {
                            InlineRespond::Done(resp) => Some(resp),
                            InlineRespond::NeedsPoolCompression(_)
                            | InlineRespond::WouldBlock(_) => None,
                        }
                    }
                    RetainedCredentialVerdict::Denied => {
                        Some(status_response(StatusCode::NOT_FOUND))
                    }
                    RetainedCredentialVerdict::FallbackFresh => {
                        drop(target);
                        if let Some(candidate_path) = selected_static_candidate {
                            return Some(serve_selected_static_representation_blocking(
                                &root,
                                &options,
                                &secret_files,
                                &forbidden,
                                candidate_path,
                                &req_path,
                                &req_query,
                                is_head,
                                &headers,
                                &sibling_probes,
                                extra_headers,
                            ));
                        }
                        match serve_blocking(
                            &root,
                            None,
                            &options,
                            &secret_files,
                            &forbidden,
                            &rel_path,
                            trailing_slash,
                            allow_dir_redirect,
                            &req_path,
                            &req_query,
                            is_head,
                            &headers,
                            InlineMode::BlockingPool,
                            None,
                            conversion.as_ref(),
                            &sibling_probes,
                            false,
                            false,
                            true,
                            extra_headers,
                        ) {
                            ServeOutcome::Done(resp) => Some(resp),
                            ServeOutcome::NeedsPoolTarget(_)
                            | ServeOutcome::FallbackPool
                            | ServeOutcome::FallbackFresh => None,
                        }
                    }
                }
            })
        })
        .await
        .ok()
        .flatten()
        .unwrap_or_else(|| status_response(StatusCode::INTERNAL_SERVER_ERROR))
    }

    /// Completes pool-deferred serving on the blocking pool for a cache-filling target already
    /// selected inline on Linux (cold compression, `RWF_NOWAIT` `WouldBlock`, or non-blocking
    /// `statx` fallback): reauthorizes the transferred descriptor after dequeue with the
    /// retained-credential predicate before reading, compressing, or admitting any bytes, keeping
    /// the selected file even if replaced on disk while queued.
    #[cfg(target_os = "linux")]
    #[allow(
        clippy::too_many_arguments,
        clippy::too_many_lines,
        clippy::fn_params_excessive_bools
    )]
    async fn finish_pool_retained_target_caching(
        &self,
        mut target: OpenedTarget<'static>,
        base_len: u64,
        forbidden: Arc<[String]>,
        rel_path: PathBuf,
        trailing_slash: bool,
        allow_dir_redirect: bool,
        path_input: &str,
        req_query: &str,
        is_head: bool,
        req_headers: &HeaderMap,
        conversion: Option<&Conversion>,
        selected_static_candidate: Option<PathBuf>,
        mut fill_ctx: FillContext,
    ) -> (Response<StaticBody>, Option<FillContext>) {
        let root = Arc::clone(&self.root);
        let options = self.options.clone();
        let secret_files = Arc::clone(&self.secret_files);
        let headers = req_headers.clone();
        let req_path = path_input.to_owned();
        let req_query = req_query.to_owned();
        let conversion = conversion.cloned();
        let sibling_probes = self.sibling_probes.clone();
        let extra_headers = self.extra_response_headers;
        let hooks = test_hooks::capture();
        match tokio::task::spawn_blocking(move || {
            let resp = test_hooks::with_captured(hooks, || {
                #[cfg(all(any(test, feature = "test-h2-hooks"), target_os = "linux"))]
                {
                    let hook = TEST_BLOCKING_POOL_HOOK
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .clone();
                    if let Some(hook) = hook {
                        hook(&target.rel_path);
                    }
                }
                test_hooks::note_pool_run();
                test_hooks::note_pool_dequeue();
                test_hooks::fire_after_pool_dequeue();
                match authorize_retained_fd(&mut target, &secret_files) {
                    RetainedCredentialVerdict::Allowed => {
                        let range_header = headers.get(RANGE).and_then(|v| v.to_str().ok());
                        if any_secret_files(&secret_files)
                            && foreign_published_has_unidentified(&secret_files)
                        {
                            match respond_with_target(
                                TargetResolution::File(target),
                                None,
                                &options,
                                &req_path,
                                &req_query,
                                is_head,
                                &headers,
                                range_header,
                                InlineMode::BlockingPool,
                                extra_headers,
                            ) {
                                InlineRespond::Done(resp) => Some(resp),
                                InlineRespond::NeedsPoolCompression(_)
                                | InlineRespond::WouldBlock(_) => None,
                            }
                        } else {
                            let refreshed_base_len = if target.encoding.is_none() {
                                target.len
                            } else {
                                base_len
                            };
                            match respond_with_target_caching(
                                TargetResolution::File(target),
                                None,
                                refreshed_base_len,
                                &options,
                                &req_path,
                                &req_query,
                                is_head,
                                &headers,
                                range_header,
                                InlineMode::BlockingPool,
                                &mut fill_ctx,
                                extra_headers,
                            ) {
                                InlineRespondCaching::Done(resp) => Some(resp),
                                InlineRespondCaching::NeedsPoolCompression(_, _)
                                | InlineRespondCaching::WouldBlock(_, _) => None,
                            }
                        }
                    }
                    RetainedCredentialVerdict::Denied => {
                        Some(status_response(StatusCode::NOT_FOUND))
                    }
                    RetainedCredentialVerdict::FallbackFresh => {
                        drop(target);
                        if let Some(candidate_path) = selected_static_candidate {
                            return Some(serve_selected_static_representation_blocking(
                                &root,
                                &options,
                                &secret_files,
                                &forbidden,
                                candidate_path,
                                &req_path,
                                &req_query,
                                is_head,
                                &headers,
                                &sibling_probes,
                                extra_headers,
                            ));
                        }
                        match serve_blocking(
                            &root,
                            None,
                            &options,
                            &secret_files,
                            &forbidden,
                            &rel_path,
                            trailing_slash,
                            allow_dir_redirect,
                            &req_path,
                            &req_query,
                            is_head,
                            &headers,
                            InlineMode::BlockingPool,
                            None,
                            conversion.as_ref(),
                            &sibling_probes,
                            false,
                            false,
                            true,
                            extra_headers,
                        ) {
                            ServeOutcome::Done(resp) => Some(resp),
                            ServeOutcome::NeedsPoolTarget(_)
                            | ServeOutcome::FallbackPool
                            | ServeOutcome::FallbackFresh => None,
                        }
                    }
                }
            });
            (resp, fill_ctx)
        })
        .await
        {
            Ok((Some(resp), fill_ctx)) => (resp, Some(fill_ctx)),
            Ok((None, fill_ctx)) => (
                status_response(StatusCode::INTERNAL_SERVER_ERROR),
                Some(fill_ctx),
            ),
            Err(_) => (status_response(StatusCode::INTERNAL_SERVER_ERROR), None),
        }
    }

    #[allow(clippy::too_many_arguments, clippy::fn_params_excessive_bools)]
    async fn serve_miss_caching(
        &self,
        forbidden: Arc<[String]>,
        rel_path: PathBuf,
        trailing_slash: bool,
        allow_dir_redirect: bool,
        path_input: &str,
        req_query: &str,
        is_head: bool,
        req_headers: &HeaderMap,
        probe: Option<LookupFound>,
        conversion: Option<&Conversion>,
        can_reuse: bool,
        can_fuse_auth: bool,
        fill_ctx: FillContext,
    ) -> (Response<StaticBody>, Option<FillContext>) {
        #[cfg(target_os = "linux")]
        if !is_head && self.should_spawn_static_task() {
            let srv = self.clone();
            let path_owned = path_input.to_owned();
            let query_owned = req_query.to_owned();
            let headers_owned = req_headers.clone();
            let conversion_owned = conversion.cloned();
            return Box::pin(run_spawned_static_task(
                async move {
                    srv.serve_miss_caching_inner(
                        forbidden,
                        rel_path,
                        trailing_slash,
                        allow_dir_redirect,
                        &path_owned,
                        &query_owned,
                        is_head,
                        &headers_owned,
                        probe,
                        conversion_owned.as_ref(),
                        can_reuse,
                        can_fuse_auth,
                        fill_ctx,
                    )
                    .await
                },
                || (status_response(StatusCode::INTERNAL_SERVER_ERROR), None),
            ))
            .await;
        }
        self.serve_miss_caching_inner(
            forbidden,
            rel_path,
            trailing_slash,
            allow_dir_redirect,
            path_input,
            req_query,
            is_head,
            req_headers,
            probe,
            conversion,
            can_reuse,
            can_fuse_auth,
            fill_ctx,
        )
        .await
    }

    #[allow(
        clippy::too_many_arguments,
        clippy::too_many_lines,
        clippy::fn_params_excessive_bools
    )]
    async fn serve_miss_caching_inner(
        &self,
        forbidden: Arc<[String]>,
        rel_path: PathBuf,
        trailing_slash: bool,
        allow_dir_redirect: bool,
        path_input: &str,
        req_query: &str,
        is_head: bool,
        req_headers: &HeaderMap,
        probe: Option<LookupFound>,
        conversion: Option<&Conversion>,
        can_reuse: bool,
        can_fuse_auth: bool,
        mut fill_ctx: FillContext,
    ) -> (Response<StaticBody>, Option<FillContext>) {
        let mut force_fresh = false;
        if let Some(mode) = self.inline_mode() {
            test_hooks::note_inline_run();
            let started = self.breaker_now();
            let served = serve_blocking_caching(
                &self.root,
                Some(&self.root_read_policy),
                &self.options,
                &self.secret_files,
                &forbidden,
                &rel_path,
                trailing_slash,
                allow_dir_redirect,
                path_input,
                req_query,
                is_head,
                req_headers,
                mode,
                probe,
                conversion,
                &self.sibling_probes,
                can_reuse,
                can_fuse_auth,
                false,
                &mut fill_ctx,
                self.extra_response_headers,
            );
            self.note_inline_lookup(started);
            match served {
                ServeOutcomeCaching::Done(resp) => return (resp, Some(fill_ctx)),
                #[cfg(target_os = "linux")]
                ServeOutcomeCaching::NeedsPoolTarget(target, base_len) => {
                    return self
                        .finish_pool_retained_target_caching(
                            target,
                            base_len,
                            forbidden,
                            rel_path,
                            trailing_slash,
                            allow_dir_redirect,
                            path_input,
                            req_query,
                            is_head,
                            req_headers,
                            conversion,
                            None,
                            fill_ctx,
                        )
                        .await;
                }
                ServeOutcomeCaching::FallbackPool => {}
                ServeOutcomeCaching::FallbackFresh => {
                    force_fresh = true;
                }
            }
        }

        let root = Arc::clone(&self.root);
        let options = self.options.clone();
        let secret_files = Arc::clone(&self.secret_files);
        let headers = req_headers.clone();
        let req_path = path_input.to_owned();
        let req_query = req_query.to_owned();
        let conversion = conversion.cloned();
        let sibling_probes = self.sibling_probes.clone();
        let extra_headers = self.extra_response_headers;
        let hooks = test_hooks::capture();
        match tokio::task::spawn_blocking(move || {
            let resp = test_hooks::with_captured(hooks, || {
                test_hooks::note_pool_run();
                test_hooks::note_pool_dequeue();
                test_hooks::fire_after_pool_dequeue();
                match serve_blocking_caching(
                    &root,
                    None,
                    &options,
                    &secret_files,
                    &forbidden,
                    &rel_path,
                    trailing_slash,
                    allow_dir_redirect,
                    &req_path,
                    &req_query,
                    is_head,
                    &headers,
                    InlineMode::BlockingPool,
                    None,
                    conversion.as_ref(),
                    &sibling_probes,
                    false,
                    false,
                    force_fresh,
                    &mut fill_ctx,
                    extra_headers,
                ) {
                    ServeOutcomeCaching::Done(resp) => Some(resp),
                    #[cfg(target_os = "linux")]
                    ServeOutcomeCaching::NeedsPoolTarget(_, _) => None,
                    ServeOutcomeCaching::FallbackPool | ServeOutcomeCaching::FallbackFresh => None,
                }
            });
            (resp, fill_ctx)
        })
        .await
        {
            Ok((Some(resp), fill_ctx)) => (resp, Some(fill_ctx)),
            Ok((None, fill_ctx)) => (
                status_response(StatusCode::INTERNAL_SERVER_ERROR),
                Some(fill_ctx),
            ),
            Err(_) => (status_response(StatusCode::INTERNAL_SERVER_ERROR), None),
        }
    }

    /// Whether a `GET` for this path would find something to serve or redirect to. The lookup
    /// is the one `GET` uses (same confinement, index and visibility rules) but stops once the
    /// file is found: it does not pick a representation, read the body or compress anything.
    async fn get_would_find(
        &self,
        forbidden: Arc<[String]>,
        rel_path: PathBuf,
        trailing_slash: bool,
        allow_dir_redirect: bool,
    ) -> bool {
        if let Some(mode) = self.inline_mode() {
            let started = self.breaker_now();
            let found = fast_resolve(
                &self.root,
                &self.options,
                &self.secret_files,
                &forbidden,
                &rel_path,
                trailing_slash,
                allow_dir_redirect,
                &HeaderMap::new(),
                true,
                None,
                &self.sibling_probes,
                false,
                mode.is_nonblocking(),
            );
            self.note_inline_lookup(started);
            if let FastResolveOutcome::Resolved(resolution) = found {
                return !matches!(resolution, TargetResolution::NotFound);
            }
        }
        let root = Arc::clone(&self.root);
        let options = self.options.clone();
        let secret_files = Arc::clone(&self.secret_files);
        let sibling_probes = self.sibling_probes.clone();
        let hooks = test_hooks::capture();
        tokio::task::spawn_blocking(move || {
            test_hooks::with_captured(hooks, || {
                test_hooks::note_pool_run();
                !matches!(
                    resolve_target(
                        &root,
                        &options,
                        &secret_files,
                        &forbidden,
                        &rel_path,
                        trailing_slash,
                        allow_dir_redirect,
                        &HeaderMap::new(),
                        true,
                        &sibling_probes,
                        false,
                    ),
                    TargetResolution::NotFound
                )
            })
        })
        .await
        .unwrap_or(false)
    }

    /// Evaluates a `try-files` candidate sequence such as `["{path}", "{path}/", "/index.php?{query}"]`
    /// for a raw (percent-encoded) `uri_path`.
